mapper.select:
select con.Con_Name as conName, con.Con_Code as conCode,
sec.Sec_Name as secName, c1.C_Name_History as wrCNameHistory, c1.C_Name as wrCName, c2.C_Name as wrContractorName, c1.C_Abbreviation as wrCAbbName, c2.C_Abbreviation as wrContractorAbbName, sd.D_Name as wrDName, mn.* from OA_Work_Report mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Company c1 on mn.Wr_C_Id=c1.C_Id left join SYS_Company c2 on mn.Wr_Contractor_Id=c2.C_Id left join SYS_Department sd on mn.Wr_D_Id=sd.D_Id
${params.authSql}
where 1=1
and sd.d_name like concat( #{params.wrDName},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Wr_Create_Time DESC

select con.Con_Name as conName, con.Con_Code as conCode,
sec.Sec_Name as secName, c1.C_Name_History as wrCNameHistory, c1.C_Name as wrCName, c2.C_Name as wrContractorName, c1.C_Abbreviation as wrCAbbName, c2.C_Abbreviation as wrContractorAbbName, sd.D_Name as wrDName, COALESCE(det.wrdNumberTotal, 0) as wrdNumberTotal, mn.* from OA_Work_Report mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Company c1 on mn.Wr_C_Id=c1.C_Id left join SYS_Company c2 on mn.Wr_Contractor_Id=c2.C_Id left join SYS_Department sd on mn.Wr_D_Id=sd.D_Id left join ( select Wr_Id, sum(COALESCE(Wrd_Number, 0)) as wrdNumberTotal from OA_Work_Report_Detail group by Wr_Id ) det on det.Wr_Id = mn.Wr_Id
${params.authSql}
where 1=1
and sd.d_name like concat( #{params.wrDName},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Wr_Create_Time DESC

select * from ( SELECT m.project_name, m.projectId, m.function_code, m.function_name, sum(m.alreadySubmissions) alreadySubmissions FROM(SELECT b.project_name, b.project_id projectId, b.function_code, b.function_name, ifnull( a.alreadySubmissions, 0 ) alreadySubmissions FROM function_time_config b LEFT JOIN ( SELECT mn.P_Id AS projectId, count( 1 ) alreadySubmissions FROM OA_Work_Report mn LEFT JOIN holiday_judge hj ON hj.date = to_char ( mn.wr_Date, 'yyyyMMdd' ) and hj.workday = 1 INNER JOIN function_time_config ftc ON ftc.project_id = mn.P_Id
${authSql}
where 1=1
and ftc.is_work = '1' AND mn.wr_Type = '04010101' AND ftc.delete_status = '0' AND mn.wr_State = '7' and hj.date >= to_char(ftc.start_time,'yyyyMMdd') and hj.date <= to_char(ftc.end_time,'yyyyMMdd') GROUP BY mn.P_Id ) a ON b.project_id = a.projectId where b.delete_status = '0'
and b.project_name like concat( '%',#{projectName},'%')
and b.project_id=#{pId}
union all SELECT b.project_name, b.project_id projectId, b.function_code, b.function_name, ifnull( a.alreadySubmissions, 0 ) alreadySubmissions FROM function_time_config b LEFT JOIN ( SELECT mn.P_Id AS projectId, count( 1 ) alreadySubmissions FROM OA_Work_Report mn LEFT JOIN holiday_judge hj ON hj.date = to_char ( mn.wr_Date, 'yyyyMMdd' ) INNER JOIN function_time_config ftc ON ftc.project_id = mn.P_Id
${authSql}
where 1=1
and ftc.is_work = '0' AND mn.wr_Type = '04010101' AND ftc.delete_status = '0' AND mn.wr_State = '7' and hj.date >= to_char(ftc.start_time,'yyyyMMdd') and hj.date <= to_char(ftc.end_time,'yyyyMMdd') GROUP BY mn.P_Id ) a ON b.project_id = a.projectId where b.delete_status = '0'
and b.project_id=#{pId}
and b.project_name like concat( '%',#{projectName},'%') ) m group by m.project_name, m.projectId , m.function_code, m.function_name ) c ${ew.customSqlSegment}

select to_char(to_date(hj.date,'yyyy-mm-dd'),'yyyy-mm-dd') noSubDate from holiday_judge hj where 1=1 and hj.date >= #{startTime} and hj.date <= #{endTime}
and hj.workday = '1'
and to_char(to_date(hj.date,'yyyy-mm-dd'),'yyyymmdd') not in ( select hj.date subDate from holiday_judge hj left join OA_Work_Report awr on to_char( awr.wr_Date,'yyyyMMdd') == hj.date where 1=1 and awr.wr_state = 7 and awr.wr_Type ='04010101' and hj.date >= #{startTime} and hj.date <= #{endTime}
and hj.workday = '1'
and awr.p_id=#{projectId} order by hj.date) order by to_date(hj.date,'yyyy-mm-dd')

