and b.project_id=#{pId}
and b.project_name like concat( '%',#{projectName},'%') ) m group by m.project_name, m.projectId , m.function_code, m.function_name ) c ${ew.customSqlSegment}

select date_format(hj.date,'%Y-%m-%d') noSubDate from holiday_judge hj where 1=1 and hj.date >= #{startTime} and hj.date <= #{endTime}
and hj.workday = '1'
and date_format(hj.date,'%Y%m%d') not in ( select hj.date subDate from holiday_judge hj left join OA_Work_Report awr on date_format(awr.wr_Date,'%Y%m%d') == hj.date where 1=1 and awr.wr_state = 7 and awr.wr_Type ='04010101' and hj.date >= #{startTime} and hj.date <= #{endTime}
and hj.workday = '1'
and awr.p_id=#{projectId} order by hj.date) order by date_format(hj.date,'%Y-%m-%d')

